/* Phase18: local review clock and production-aligned scheduling. No system clock or app data. */
(() => {
  const shift=(key,days)=>{const d=dateFromKey(key);d.setDate(d.getDate()+days);return dateKey(d);};
  const completeToday=()=>tasks.filter(t=>!isQuick(t)&&t.done&&(t.resolvedAt===demoToday||t.recurrence?.lastCompletedOccurrence===demoToday));
  let savedScene=null;
  function sample(id,title,cycle=false){return {id,kind:'task',title,group:'技术排查',priority:'medium',today:false,done:cycle,createdAt:'2026-10-01',updatedAt:'2026-10-01',resolvedAt:cycle?'2026-10-01':'',deadlineAt:cycle?'':'2026-10-02',deadlineTime:cycle?'':'18:00',deadline:cycle?'':'10 月 2 日',deadlineReminderMinutes:60,tags:{blocked:false,later:false},recurrence:{frequency:cycle?'daily':'none',time:'09:00',weekdays:[1,2,3,4,5],lastCompletedOccurrence:cycle?'2026-10-01':''},description:cycle?'每天核对构建产物与日志，记录异常。':'核对设备侧与内核侧日志的时间戳，确认可以对照事件顺序。',progress:'验证记录已整理。',conclusion:cycle?'昨日构建通过，未发现异常。':'日志时间戳可直接对照，偏差在允许范围内。',nodes:[node('time18-'+id,'核对日志并保留验证结果','done',[],'已检查时间戳、事件顺序与构建结果。')],notes:cycle?'# 每日构建\n\n保留上一次验证记录，下一轮在此继续。':'# 时间戳核对\n\n设备侧与内核侧日志已对照。',history:[['2026-10-01 09:30','保留验证结果']]};}
  tasks.unshift(sample(18001,'验证日志时间戳'),sample(18002,'检查每日构建日志',true));
  function syncClock(){tasks.forEach(t=>{const occurrence=recurrenceOccurrence(t);if(occurrence&&t.recurrence.lastCompletedOccurrence!==occurrence&&t.done){t.done=false;t.resolvedAt='';t.updatedAt=demoToday;}});}
  const priorScope=recordsInScope;
  recordsInScope=function(){if(state.route==='today'&&state.recordType!=='quick'&&['done','all'].includes(state.filter))return tasks.filter(t=>isQuick(t)?state.recordType==='all':state.filter==='done'?completeToday().includes(t):scheduledToday(t)||completeToday().includes(t));return priorScope();};
  matchesDeadline=function(t){if(state.deadlineDate)return t.deadlineAt===state.deadlineDate;if(state.deadlineScope==='all')return true;if(!t.deadlineAt)return false;if(state.deadlineScope==='today')return t.deadlineAt===demoToday;if(state.deadlineScope==='overdue')return !t.done&&deadlineStamp(t)<demoNow;const d=dateFromKey(demoToday),monday=shift(demoToday,-((d.getDay()+6)%7));return t.deadlineAt>=monday&&t.deadlineAt<shift(monday,7);};
  const priorRange=reviewRange;
  reviewRange=function(){const r=priorRange(),d=dateFromKey(demoToday);if(state.reviewPreset==='month'){r.start=dateKey(new Date(d.getFullYear(),d.getMonth(),1));r.end=dateKey(new Date(d.getFullYear(),d.getMonth()+1,0));}if(state.reviewPreset==='year'){r.start=d.getFullYear()+'-01-01';r.end=d.getFullYear()+'-12-31';}if(['month','year'].includes(state.reviewPreset))r.label=displayDate(r.start)+' — '+displayDate(r.end);return r;};
  const priorProperties=renderTaskProperties;
  renderTaskProperties=function(t){
    const wrapper=document.createElement('div');wrapper.innerHTML=priorProperties(t);const b=wrapper.querySelector('[data-action="edit-deadline"]');
    if(t.deadlineAt&&b){const minutes=Math.round((new Date(deadlineStamp(t))-new Date(demoNow))/60000),near=!t.done&&minutes>=0&&minutes<=60,late=!t.done&&minutes<0;let text=(t.deadlineAt===demoToday?'今天':displayDate(t.deadlineAt))+' '+(t.deadlineTime||'18:00');if(near)text=(minutes?'还剩 '+minutes+' 分钟':'即将截止')+' · '+(t.deadlineTime||'18:00');if(late){const n=-minutes;text='逾期 '+(n<60?n+' 分钟':n<1440?Math.floor(n/60)+' 小时':Math.floor(n/1440)+' 天')+' · '+(t.deadlineAt===demoToday?t.deadlineTime:displayDate(t.deadlineAt));}b.classList.toggle('time18-soon',near);b.innerHTML=icon('calendar')+esc(text)+icon('down');b.title=t.deadlineAt+' '+(t.deadlineTime||'18:00')+' · '+(t.deadlineReminderMinutes==null?'不提醒':reminderNames[t.deadlineReminderMinutes]||'提前 '+t.deadlineReminderMinutes+' 分钟提醒');}
    return wrapper.innerHTML;
  };
  const priorList=renderTaskList;
  renderTaskList=function(list){if(!list.length&&state.route==='today'&&state.recordType==='task'&&state.priority==='all'&&state.deadlineScope==='all'&&!state.deadlineDate)return '<div class="empty time18-list-empty">'+(state.filter==='done'?'今天暂无完成任务':'暂无待办')+'</div>';return priorList(list);};
  const priorEmpty=renderEmptyWorkspace;
  renderEmptyWorkspace=function(){if(state.route==='today'&&state.recordType==='task'&&state.filter==='active'&&state.priority==='all'&&state.deadlineScope==='all'&&!state.deadlineDate){const n=completeToday().length;return `<div class="workspace-empty time18-empty"><span>${n?'今日任务已完成':'今天暂无任务'}</span>${n?'<button class="text-button" data-time18="completed">查看完成任务'+icon('arrow')+'</button>':''}</div>`;}return priorEmpty();};
  function feedback(message,t){clearTimeout(toastTimer);$('#toast').innerHTML=`<div class="toast"><span>${esc(message)}</span>${t?`<button data-time18="record" data-record="${t.id}">查看任务${icon('arrow')}</button>`:''}</div>`;toastTimer=setTimeout(()=>$('#toast').innerHTML='',6000);}
  function membershipFeedback(t,before){if(before&&!scheduledToday(t))feedback('已移出今日，任务与处理记录保留',t);else if(state.route==='today'&&scheduledToday(t))feedback(t.today?'已更新，手动加入的任务继续留在今日':'已更新今日安排');else feedback('已更新任务安排');}
  const priorDeadline=showDeadline;
  showDeadline=function(trigger,reset=true){const t=currentTask(),before=scheduledToday(t);priorDeadline(trigger,reset);const f=$('#deadline-form');const tomorrow=f.querySelectorAll('[data-schedule-day]')[1];if(tomorrow)tomorrow.dataset.scheduleDay=shift(demoToday,1);f.addEventListener('submit',()=>{if(!$('#deadline-form'))membershipFeedback(t,before);});};
  const priorCycle=showRecurrence;
  showRecurrence=function(trigger,reset=true){const t=currentTask(),before=scheduledToday(t);priorCycle(trigger,reset);const f=$('#recurrence-form'),r=state.recurrenceDraft;if(r.frequency!=='none'){const occurrence=recurrenceOccurrence(t),done=t.recurrence?.lastCompletedOccurrence===demoToday;f.querySelector('.recurrence-modes').insertAdjacentHTML('afterend',`<p class="time18-cycle-state">${done?'本次已完成':occurrence?'本次待处理':'尚未到本次时间'}<span> · ${displayDate(demoToday)}</span></p>`);f.style.top=Math.max(12,Math.min(parseFloat(f.style.top),innerHeight-50-f.offsetHeight))+'px';}f.addEventListener('submit',()=>{if(!$('#recurrence-form'))membershipFeedback(t,before);});};
  function setClock(value){const oldDay=demoToday;demoNow=value;demoToday=value.slice(0,10);if(state.calendarDate===oldDay){state.calendarDate=demoToday;state.calendarMonth=demoToday.slice(0,7);}syncClock();closeOverlay();ensureSelection();render();feedback('预览时间已切换 · '+demoNow.replace('T',' '));}
  const presets=[['2026-10-02T10:00','初始时间'],['2026-10-02T17:30','截止前 30 分钟'],['2026-10-02T18:15','截止后 15 分钟'],['2026-10-03T08:30','次日循环前'],['2026-10-03T09:00','次日循环到期'],['2026-10-09T09:00','下周五']];
  function showClock(trigger){mountSurface(`<form id="time18-clock-form" class="surface-popover entry16-panel time18-clock" role="dialog" aria-modal="true" aria-label="预览时间">${surfaceHeader('预览时间')}<p class="schedule-hint">仅改变示例时间；本页的操作与记录会保留。</p><div class="schedule-fields"><div><label for="time18-day">日期</label><input id="time18-day" name="day" type="date" value="${demoToday}" min="2026-01-01" max="2027-12-31" required></div><div><label for="time18-hour">时间</label><input id="time18-hour" name="hour" type="time" value="${demoNow.slice(11)}" required></div></div><div class="time18-presets" role="group" aria-label="时间场景">${presets.map(([value,label])=>`<button type="button" data-time18-preset="${value}" class="${value===demoNow?'active':''}" aria-pressed="${value===demoNow}"><span>${label}</span><time>${value.slice(5).replace('T',' ')}</time></button>`).join('')}</div><div class="time18-scenes"><span>独立状态示例</span><button type="button" data-time18="scene-done">今日全部完成</button><button type="button" data-time18="scene-empty">今日无任务</button></div><footer><button type="button" class="button" data-action="close-dialog">取消</button><button class="button primary" type="submit">应用时间</button></footer></form>`,trigger,360);$('#time18-clock-form').addEventListener('submit',e=>{e.preventDefault();const f=new FormData(e.target);setClock(String(f.get('day'))+'T'+String(f.get('hour')));});}
  function scene(done){if(!savedScene)savedScene={tasks:structuredClone(tasks),state:structuredClone(state),now:demoNow};const a=sample(18101,'整理并保留今日验证结论');Object.assign(a,{done:true,today:done,deadlineAt:'',deadlineTime:'',resolvedAt:done?demoToday:shift(demoToday,-1)});const b=sample(18102,'检查下一次构建结果');Object.assign(b,{deadlineAt:shift(demoToday,1)});tasks.splice(0,tasks.length,a,b);Object.assign(state,{route:'today',recordType:'task',group:'all',filter:'active',priority:'all',deadlineDate:null,deadlineScope:'all',query:'',task:null,node:null,widgetType:'task',widgetOpen:true});closeOverlay();render();}
  function returnScene(){const s=savedScene;if(!s)return;savedScene=null;tasks.splice(0,tasks.length,...s.tasks);Object.assign(state,s.state);demoNow=s.now;demoToday=s.now.slice(0,10);closeOverlay();render();feedback('已返回原预览，之前的操作与草稿已恢复');}
  function showCompleted(){closeOverlay();Object.assign(state,{route:'today',recordType:'task',group:'all',filter:'done',priority:'all',deadlineDate:null,deadlineScope:'all',query:'',task:null,node:null,pane:'flow'});ensureSelection();render();}
  function record(id){const t=tasks.find(t=>t.id===Number(id));if(!t)return;Object.assign(state,{route:'tasks',recordType:'task',group:'all',filter:'all',priority:'all',deadlineDate:null,deadlineScope:'all',query:'',task:t.id,node:null,pane:'flow',backRoute:null});render();}
  const priorRender=render;
  render=function(){syncClock();priorRender();const widgetDate=$('.widget-date');if(widgetDate)widgetDate.textContent=displayDate(demoToday);if(state.route==='today'&&state.recordType==='task'){const footer=$('.list-foot'),n=completeToday().length;if(footer&&(n||state.filter==='done')){footer.classList.add('time18-footer');footer.insertAdjacentHTML('beforeend',`<button class="text-button time18-completed" data-time18="${state.filter==='done'?'active':'completed'}">${state.filter==='done'?'返回待办':'已完成 '+n}</button>`);}if(state.widgetType==='task'&&!todayTaskItems().length){const empty=$('.widget-empty');if(empty)empty.textContent=n?'今日任务已完成':'暂无今日任务';}}const note=$('.review-bar .review-note');if(note){note.innerHTML=`<button class="time18-clock-trigger" data-action="time18-clock" aria-haspopup="dialog" aria-expanded="false" title="切换示例日期与时间">${icon('clock')}<span>${savedScene?'独立状态示例':demoNow.replace('T',' ')}</span>${icon('down')}</button>${savedScene?'<button class="text-button" data-time18="return-scene">返回原预览</button>':''}`;}};
  window.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;const action=b.dataset.time18;if(b.dataset.action==='time18-clock'||b.dataset.time18Preset||action){e.preventDefault();e.stopImmediatePropagation();if(b.dataset.action==='time18-clock')showClock(b);else if(b.dataset.time18Preset)setClock(b.dataset.time18Preset);else if(action==='completed')showCompleted();else if(action==='active'){state.filter='active';ensureSelection();render();}else if(action==='record')record(b.dataset.record);else if(action==='scene-done'||action==='scene-empty')scene(action==='scene-done');else if(action==='return-scene')returnScene();return;}if(b.dataset.action==='remove-deadline'){const t=currentTask(),before=scheduledToday(t);Object.assign(t,{deadlineAt:'',deadlineTime:'',deadline:''});touchTask(t);closeOverlay();ensureSelection();render();membershipFeedback(t,before);e.preventDefault();e.stopImmediatePropagation();}},true);
  globalThis.loopTime18Review=function(){mountSurface(`<section class="surface-popover entry16-panel time18-review" role="dialog" aria-modal="true" aria-label="第十八阶段评审">${surfaceHeader('第十八阶段 · 时间与状态')}<ol><li>选择“验证日志时间戳”，切到截止前／后，查看详情中的时间提示。</li><li>完成“检查每日构建日志”，切到次日循环前，再切到循环到期；查看任务重新出现，记录保留。</li><li>修改截止日期，查看今日任务与浮窗同步，以及任务找回入口。</li><li>载入今日全部完成／无任务示例；看完点击“返回原预览”。</li></ol><p class="schedule-hint">时间仅用于设计检阅，不改变系统时间。没有真实通知或后台调度；刷新恢复初始示例。</p></section>`,$('#reviewInfo'),390);};
  reviewInfo=globalThis.loopTime18Review;globalThis.loopWidgetReview=globalThis.loopTime18Review;
  document.title='Loop · 第十八阶段设计';$('.review-bar b').textContent='第十八阶段 · 时间与状态';state.route='today';state.task=18001;syncClock();ensureSelection();render();
})();
